import pytest
from src.classifier.api import ClassifyRequest

def test_classify_endpoint_success(client, mock_llm_client):
    response = client.post("/classify", json={
        "profile": "receipt",
        "ocr_text": "HOME DEPOT ... TOTAL 42.17 ... 12/04/25",
        "note_text": "hardware for gym project",
        "hints": {
            "fallback_date": "2025-12-04",
            "source_filename": "receipt_2025-12-04T15-30-12.jpg",
            "source_channel": "email",
