## 20. Client SDK Patterns

### 20.1 TypeScript Client

```typescript
class CarouselClient {
  constructor(baseUrl: string, token: string);

  // Sessions
  listSessions(query?: ListSessionsQuery): Promise<ListSessionsResponse>;
  createSession(req: CreateSessionRequest): Promise<CreateSessionResponse>;
  getSession(sessionId: string): Promise<GetSessionResponse>;
  deleteSession(sessionId: string): Promise<void>;

  // Messages
  sendMessage(sessionId: string, content: string): Promise<SendMessageResponse>;
  onStreamChunk(callback: (chunk: StreamChunk) => void): void;

  // WebSocket
  connect(): Promise<void>;
  subscribe(sessionId: string): void;
  dispatch(action: Action): void;
  onStateUpdate(callback: (state: Partial<ApplicationState>) => void): void;
}
```

### 20.2 Usage Example

```typescript
const client = new CarouselClient("https://api.carousel.example.com/v1", token);

// Connect WebSocket
await client.connect();

// Create session
const { session } = await client.createSession({ title: "New Chat" });

// Subscribe to updates
client.subscribe(session.id);

// Handle state updates
client.onStateUpdate((state) => {
  renderUI(state);
});

// Send message
await client.sendMessage(session.id, "Hello, world!");

// Handle streaming
client.onStreamChunk((chunk) => {
  appendToCard(chunk.cardId, chunk.content);
});
```

