# Carousel Interface: JSON Schema

**Project:** Turn-Centric Cognitive Interface
**Component:** Data Schema Specification
**Status:** Draft
**Last Updated:** December 2025

---

## 1. Purpose

The JSON schema defines how the backend communicates UI state to the frontend. This separation enables:

- **Platform independence** - Same schema, different renderers
- **AI-driven UI** - Backend can modify layout dynamically
- **MCP compatibility** - External clients can render the interface
- **Rapid iteration** - Change UI without frontend deploys

The frontend is a **dumb renderer**. All logic lives in the backend.

---

## 2. Schema Overview

```
ApplicationState
├── session: SessionState
├── carousel: CarouselState
├── quadrants: QuadrantState
├── threads: ThreadState[]
└── ui: UIState
```

---

## 3. Session State

```typescript
interface SessionState {
  id: string;
  title: string;
  mode: SessionMode;
  createdAt: string;         // ISO 8601
  updatedAt: string;
  branches: Branch[];
  activeBranchId: string;
  checkpoints: Checkpoint[];
  context: ContextState;
}

type SessionMode = "strict" | "creative" | "analytical" | "writing";

interface Branch {
  id: string;
  name: string;
  parentBranchId: string | null;
  forkPoint: number;         // Card index where branched
  createdAt: string;
}

interface Checkpoint {
  id: string;
  name: string;
  timestamp: string;
  branchId: string;
  cardIndex: number;
}

interface ContextState {
  personaId: string;
  documentIds: string[];
  domains: string[];
  customInstructions: string | null;
}
```

### Example

```json
{
  "id": "sess_abc123",
  "title": "Carousel Architecture Design",
  "mode": "analytical",
  "createdAt": "2025-12-06T10:00:00Z",
  "updatedAt": "2025-12-06T14:30:00Z",
  "branches": [
    {
      "id": "branch_main",
      "name": "main",
      "parentBranchId": null,
      "forkPoint": 0,
      "createdAt": "2025-12-06T10:00:00Z"
    }
  ],
  "activeBranchId": "branch_main",
  "checkpoints": [],
  "context": {
    "personaId": "architect",
    "documentIds": ["doc_design", "doc_api"],
    "domains": ["software", "ui"],
    "customInstructions": null
  }
}
```

---

## 4. Carousel State

```typescript
interface CarouselState {
  cards: TurnCard[];
  selectedIndex: number;
  isLoading: boolean;
  loadingCardId: string | null;
}

interface TurnCard {
  id: string;
  index: number;
  branchId: string;

  // Content
  title: string;
  titleEdited: boolean;
  userContent: ContentBlock[];
  aiContent: ContentBlock[];

  // State
  collapsed: boolean;
  state: CardState;

  // Metadata
  tags: string[];
  timestamp: string;
  promotedFrom: string | null;  // Thread ID if promoted

  // Computed (backend provides)
  wordCount: number;
  hasCode: boolean;
  hasTables: boolean;
}

type CardState = "default" | "loading" | "error" | "streaming";

interface ContentBlock {
  type: ContentBlockType;
  content: string;
  language?: string;         // For code blocks
  alt?: string;              // For images
}

type ContentBlockType = "text" | "code" | "image" | "table" | "list";
```

