## 6. Widget Schema

Widgets are the atomic UI elements rendered in quadrants.

### 6.1 Base Widget

```typescript
interface BaseWidget {
  id: string;
  type: WidgetType;
  visible: boolean;
  disabled: boolean;
  className?: string;
}

type WidgetType =
  | "button"
  | "button-group"
  | "select"
  | "text-input"
  | "textarea"
  | "label"
  | "divider"
  | "list"
  | "list-item"
  | "pills"
  | "pill"
  | "card-info"
  | "spacer"
  | "container";
```

### 6.2 Button Widget

```typescript
interface ButtonWidget extends BaseWidget {
  type: "button";
  props: {
    label: string;
    icon?: string;           // Lucide icon name
    variant: "primary" | "secondary" | "ghost";
    size: "sm" | "md" | "lg";
    action: ActionRef;
  };
}

interface ActionRef {
  type: string;              // Action type identifier
  payload?: Record<string, unknown>;
}
```

### 6.3 Select Widget

```typescript
interface SelectWidget extends BaseWidget {
  type: "select";
  props: {
    label?: string;
    value: string;
    options: SelectOption[];
    placeholder?: string;
    action: ActionRef;
  };
}

interface SelectOption {
  value: string;
  label: string;
  icon?: string;
  disabled?: boolean;
}
```

### 6.4 Text Input Widget

```typescript
interface TextInputWidget extends BaseWidget {
  type: "text-input";
  props: {
    value: string;
    placeholder?: string;
    label?: string;
    icon?: string;
    action: ActionRef;       // Triggered on change/submit
  };
}
```

### 6.5 Textarea Widget

```typescript
interface TextareaWidget extends BaseWidget {
  type: "textarea";
  props: {
    value: string;
    placeholder?: string;
    rows?: number;
    maxRows?: number;
    action: ActionRef;
  };
}
```

### 6.6 List Widget

```typescript
interface ListWidget extends BaseWidget {
  type: "list";
  props: {
    items: ListItemWidget[];
    emptyMessage?: string;
  };
}

interface ListItemWidget extends BaseWidget {
  type: "list-item";
  props: {
    label: string;
    icon?: string;
    status?: "active" | "inactive" | "muted";
    action?: ActionRef;
    secondaryAction?: ActionRef;
  };
}
```

### 6.7 Pills Widget

```typescript
interface PillsWidget extends BaseWidget {
  type: "pills";
  props: {
    items: PillWidget[];
    allowAdd?: boolean;
    addAction?: ActionRef;
  };
}

interface PillWidget extends BaseWidget {
  type: "pill";
  props: {
    label: string;
    active: boolean;
    removable: boolean;
    action: ActionRef;
    removeAction?: ActionRef;
  };
}
```

### 6.8 Card Info Widget

```typescript
interface CardInfoWidget extends BaseWidget {
  type: "card-info";
  props: {
    cardId: string;
    turnNumber: number;
    totalTurns: number;
