## 10. Action Types

Actions are events sent from frontend to backend.

```typescript
// Session actions
type SessionAction =
  | { type: "SET_MODE"; payload: { mode: SessionMode } }
  | { type: "SET_SESSION_TITLE"; payload: { title: string } }
  | { type: "SWITCH_BRANCH"; payload: { branchId: string } }
  | { type: "CREATE_CHECKPOINT"; payload: { name: string } }
  | { type: "RESTORE_CHECKPOINT"; payload: { checkpointId: string } };

// Context actions
type ContextAction =
  | { type: "SET_PERSONA"; payload: { personaId: string } }
  | { type: "TOGGLE_DOCUMENT"; payload: { id: string } }
  | { type: "TOGGLE_DOMAIN"; payload: { domain: string } }
  | { type: "ADD_DOMAIN"; payload: { domain: string } }
  | { type: "REMOVE_DOMAIN"; payload: { domain: string } };

// Card actions
type CardAction =
  | { type: "SELECT_CARD"; payload: { index: number } }
  | { type: "TOGGLE_COLLAPSE"; payload: { cardId: string } }
  | { type: "EDIT_TITLE"; payload: { cardId: string; title: string } }
  | { type: "ADD_TAG"; payload: { cardId: string; tag: string } }
  | { type: "REMOVE_TAG"; payload: { cardId: string; tag: string } }
  | { type: "BRANCH_AT_CARD"; payload: { cardId: string } }
  | { type: "CONVERT_CARD"; payload: { cardId: string; to: ArtifactType } }
  | { type: "DELETE_CARD"; payload: { cardId: string } };

// Message actions
type MessageAction =
  | { type: "SEND_MESSAGE"; payload: { content: string } }
  | { type: "SEARCH"; payload: { query: string } };

// Thread actions
type ThreadAction =
  | { type: "CREATE_SIDE_THREAD"; payload?: { fromCardId?: string } }
  | { type: "MINIMIZE_THREAD"; payload: { threadId: string } }
  | { type: "RESTORE_THREAD"; payload: { threadId: string } }
  | { type: "CLOSE_THREAD"; payload: { threadId: string } }
  | { type: "PIN_THREAD"; payload: { threadId: string } }
  | { type: "SEND_THREAD_MESSAGE"; payload: { threadId: string; content: string } }
  | { type: "PROMOTE_CARD"; payload: { threadId: string; cardId: string } }
  | { type: "PROMOTE_THREAD"; payload: { threadId: string } };

// Combined action type
type Action =
  | SessionAction
  | ContextAction
  | CardAction
  | MessageAction
  | ThreadAction;
```

