## 4. Carousel State

```typescript
interface CarouselState {
  cards: TurnCard[];
  selectedIndex: number;
  isLoading: boolean;
  loadingCardId: string | null;
}

interface TurnCard {
  id: string;
  index: number;
  branchId: string;

  // Content
  title: string;
  titleEdited: boolean;
  userContent: ContentBlock[];
  aiContent: ContentBlock[];

  // State
  collapsed: boolean;
  state: CardState;

  // Metadata
  tags: string[];
  timestamp: string;
  promotedFrom: string | null;  // Thread ID if promoted

  // Computed (backend provides)
  wordCount: number;
  hasCode: boolean;
  hasTables: boolean;
}

type CardState = "default" | "loading" | "error" | "streaming";

interface ContentBlock {
  type: ContentBlockType;
  content: string;
  language?: string;         // For code blocks
  alt?: string;              // For images
}

type ContentBlockType = "text" | "code" | "image" | "table" | "list";
```

### Example

```json
{
  "cards": [
    {
      "id": "card_001",
      "index": 0,
      "branchId": "branch_main",
      "title": "What is the carousel architecture?",
      "titleEdited": false,
      "userContent": [
        {
          "type": "text",
          "content": "Can you explain the carousel architecture?"
        }
      ],
      "aiContent": [
        {
          "type": "text",
