          "language": "typescript"
        }
      ],
      "collapsed": false,
      "state": "default",
      "tags": ["architecture"],
      "timestamp": "2025-12-06T10:05:00Z",
      "promotedFrom": null,
      "wordCount": 234,
      "hasCode": true,
      "hasTables": false
    }
  ],
  "selectedIndex": 0,
  "isLoading": false,
  "loadingCardId": null
}
