// Card actions
type CardAction =
  | { type: "SELECT_CARD"; payload: { index: number } }
  | { type: "TOGGLE_COLLAPSE"; payload: { cardId: string } }
  | { type: "EDIT_TITLE"; payload: { cardId: string; title: string } }
