  | { type: "CONVERT_CARD"; payload: { cardId: string; to: ArtifactType } }
  | { type: "DELETE_CARD"; payload: { cardId: string } };

// Message actions
type MessageAction =
  | { type: "SEND_MESSAGE"; payload: { content: string } }
  | { type: "SEARCH"; payload: { query: string } };

// Thread actions
type ThreadAction =
  | { type: "CREATE_SIDE_THREAD"; payload?: { fromCardId?: string } }
  | { type: "MINIMIZE_THREAD"; payload: { threadId: string } }
  | { type: "RESTORE_THREAD"; payload: { threadId: string } }
  | { type: "CLOSE_THREAD"; payload: { threadId: string } }
  | { type: "PIN_THREAD"; payload: { threadId: string } }
  | { type: "SEND_THREAD_MESSAGE"; payload: { threadId: string; content: string } }
  | { type: "PROMOTE_CARD"; payload: { threadId: string; cardId: string } }
  | { type: "PROMOTE_THREAD"; payload: { threadId: string } };

// Combined action type
type Action =
  | SessionAction
  | ContextAction
  | CardAction
  | MessageAction
  | ThreadAction;
