   118→
   119→## 4. Artifact Engine Integration
   120→
   121→### 4.1 Artifact Client
   122→
   123→A simple HTTP client that wraps Artifact Engine's API:
   124→
   125→```typescript
   126→// services/artifact-client.ts
   127→import { config } from "../config";
   128→
   129→const ARTIFACT_ENGINE_URL = config.artifactEngineUrl; // http://localhost:3002
   130→
   131→export const artifactClient = {
   132→  // Get registry to discover available domains/categories
   133→  async getLocations(): Promise<LocationRegistry> {
   134→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/registry/locations`);
   135→    return res.json();
   136→  },
   137→
   138→  // Search for documents by domain/category
   139→  async search(query: ArtifactSearchQuery): Promise<ArtifactSearchResult[]> {
   140→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/search`, {
   141→      method: "POST",
   142→      headers: { "Content-Type": "application/json" },
   143→      body: JSON.stringify(query),
   144→    });
   145→    return res.json();
   146→  },
   147→
   148→  // Get document content by ID
   149→  async getContent(artifactId: string): Promise<string> {
   150→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/${artifactId}/content`);
   151→    return res.text();
   152→  },
   153→
   154→  // Get document metadata
   155→  async getMetadata(artifactId: string): Promise<ArtifactMetadata> {
   156→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/${artifactId}`);
   157→    return res.json();
   158→  },
   159→};
   160→
   161→interface ArtifactSearchQuery {
   162→  domain?: string;           // e.g., "whitepapers"
   163→  category?: string;         // e.g., "sdb-framework"
   164→  keywords?: string[];       // filename token matching
   165→  tags?: string[];           // inferred from registry
   166→}
   167→
   168→interface ArtifactSearchResult {
   169→  id: string;
   170→  path: string;
   171→  filename: string;
   172→  domain: string;
   173→  category: string;
   174→  tags: string[];
   175→}
   176→
   177→interface ArtifactMetadata {
   178→  id: string;
   179→  path: string;
   180→  filename: string;
   181→  domain: string;
   182→  category: string;
   183→  tags: string[];
   184→  topics: string[];
   185→  // Inferred from filename tokens and registry
   186→}
   187→```
   188→
   189→### 4.2 Scope Discovery
   190→
   191→The West quadrant dropdown is populated from Artifact Engine's registry:
   192→
   193→```typescript
   194→// services/context-assembler.ts
   195→export const getAvailableScopes = async (): Promise<ContextScope[]> => {
   196→  const locations = await artifactClient.getLocations();
   197→
   198→  // Find the whitepapers domain
   199→  const whitepaperLocation = locations.find(l => l.prefix === "whitepapers");
   200→  if (!whitepaperLocation) return [];
   201→
   202→  const scopes: ContextScope[] = [
   203→    { type: "all", label: "All Whitepapers" }
   204→  ];
   205→
   206→  // Add categories as groups
   207→  for (const category of whitepaperLocation.categories || []) {
   208→    scopes.push({
   209→      type: "group",
   210→      groupId: category.id,
   211→      label: category.name,
   212→    });
   213→  }
   214→
   215→  // Add individual documents
   216→  const allDocs = await artifactClient.search({ domain: "whitepapers" });
   217→  for (const doc of allDocs) {
   218→    scopes.push({
   219→      type: "document",
   220→      documentId: doc.id,
   221→      label: inferTitle(doc.filename),
   222→    });
   223→  }
   224→
   225→  return scopes;
   226→};
   227→
   228→const inferTitle = (filename: string): string => {
   229→  // software_defined_business.md → "Software Defined Business"
   230→  return filename
   231→    .replace(/\.md$/, "")
   232→    .replace(/_/g, " ")
   233→    .replace(/\b\w/g, c => c.toUpperCase());
   234→};
   235→```
   236→
   237→### 4.3 Context Assembly
   238→
   239→The "baby assembler" - fetches documents and concatenates them:
   240→
   241→```typescript
   242→// services/context-assembler.ts
   243→export const assembleContext = async (scope: ContextScope): Promise<AssembledContext> => {
   244→  let artifacts: ArtifactSearchResult[];
   245→
   246→  switch (scope.type) {
   247→    case "all":
   248→      artifacts = await artifactClient.search({ domain: "whitepapers" });
   249→      break;
   250→    case "group":
   251→      artifacts = await artifactClient.search({
   252→        domain: "whitepapers",
   253→        category: scope.groupId
   254→      });
   255→      break;
   256→    case "document":
   257→      artifacts = await artifactClient.search({
   258→        domain: "whitepapers"
   259→      }).then(all => all.filter(a => a.id === scope.documentId));
   260→      break;
   261→  }
   262→
   263→  // Fetch content for each document
   264→  const documents: AssembledDocument[] = await Promise.all(
   265→    artifacts.map(async (artifact) => ({
   266→      id: artifact.id,
   267→      title: inferTitle(artifact.filename),
   268→      content: await artifactClient.getContent(artifact.id),
   269→    }))
   270→  );
   271→
   272→  // Build the context string
   273→  const contextString = documents
   274→    .map(doc => `### ${doc.title}\n\n${doc.content}`)
   275→    .join("\n\n---\n\n");
   276→
   277→  return {
   278→    documents,
   279→    contextString,
   280→    tokenEstimate: Math.ceil(contextString.length / 4), // Rough estimate
   281→  };
   282→};
   283→
   284→interface AssembledContext {
   285→  documents: AssembledDocument[];
   286→  contextString: string;
   287→  tokenEstimate: number;
   288→}
   289→
   290→interface AssembledDocument {
   291→  id: string;
   292→  title: string;
   293→  content: string;
   294→}
   295→```
