   696→## 9. Distillation Service
   697→
   698→### 9.1 Purpose
   699→
   700→Periodically summarize the session to:
   701→- Maintain coherence in long sessions
   702→- Provide exportable notes
   703→- Reduce context window usage
   704→
   705→### 9.2 Trigger
   706→
   707→```typescript
   708→const shouldDistill = (session: Session): boolean => {
   709→  const lastDistill = session.distillation?.turnCount ?? 0;
   710→  const currentTurns = session.cards.length;
   711→
   712→  // Distill every 5 turns
   713→  return currentTurns - lastDistill >= 5;
   714→};
   715→```
   716→
   717→### 9.3 Distillation Prompt
   718→
   719→```typescript
   720→const distillSession = async (session: Session): Promise<SessionDistillation> => {
   721→  const conversationText = session.cards
   722→    .map(c => `User: ${c.userContent}\nAssistant: ${c.aiContent}`)
   723→    .join('\n\n---\n\n');
   724→
   725→  const response = await openai.chat.completions.create({
   726→    model: "gpt-4",
   727→    messages: [
   728→      {
   729→        role: "system",
   730→        content: `Analyze this conversation and provide:
   731→1. A 2-3 sentence summary of what was discussed
   732→2. Key insights or conclusions (bullet points)
   733→3. Main questions that were explored (bullet points)
   734→
   735→Be concise. This will be used as context for continuing the conversation.`
   736→      },
   737→      {
   738→        role: "user",
   739→        content: conversationText
   740→      }
   741→    ],
   742→    response_format: { type: "json_object" }
   743→  });
   744→
   745→  return JSON.parse(response.choices[0].message.content);
   746→};
   747→```
