   763→## 10. OpenAI Integration
   764→
   765→### 10.1 Client Setup
   766→
   767→```typescript
   768→// services/openai.ts
   769→import OpenAI from "openai";
   770→import { config } from "../config";
   771→
   772→export const openai = new OpenAI({
   773→  apiKey: config.openaiApiKey,
   774→});
   775→```
   776→
   777→### 10.2 Streaming Handler
   778→
   779→```typescript
   780→export const streamCompletion = async (
   781→  messages: ChatMessage[],
   782→  onChunk: (content: string, index: number) => void,
   783→  onComplete: (fullContent: string) => void,
   784→  onError: (error: Error) => void
   785→): Promise<void> => {
   786→  try {
   787→    const stream = await openai.chat.completions.create({
   788→      model: config.model,  // "gpt-4" or "gpt-4-turbo"
   789→      messages,
   790→      stream: true,
   791→    });
   792→
   793→    let fullContent = "";
   794→    let index = 0;
   795→
   796→    for await (const chunk of stream) {
   797→      const content = chunk.choices[0]?.delta?.content || "";
   798→      if (content) {
   799→        fullContent += content;
   800→        onChunk(content, index++);
   801→      }
   802→    }
   803→
   804→    onComplete(fullContent);
   805→  } catch (error) {
   806→    onError(error as Error);
   807→  }
   808→};
   809→```
   810→
   811→### 10.3 Message Building
   812→
   813→```typescript
   814→export const buildMessages = (
   815→  systemPrompt: string,
   816→  cards: TurnCard[],
   817→  newUserMessage: string
   818→): ChatMessage[] => {
   819→  const messages: ChatMessage[] = [
   820→    { role: "system", content: systemPrompt }
   821→  ];
   822→
   823→  // Add conversation history
   824→  for (const card of cards) {
   825→    messages.push({ role: "user", content: card.userContent });
   826→    messages.push({ role: "assistant", content: card.aiContent });
   827→  }
   828→
   829→  // Add new message
   830→  messages.push({ role: "user", content: newUserMessage });
   831→
   832→  return messages;
   833→};
   834→```
