   876→// storage/json.ts
   877→import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, unlinkSync } from "fs";
   878→import { join } from "path";
   879→import { config } from "../config";
   880→
   881→const sessionsDir = join(config.dataDir, "sessions");
