   883→// Ensure directory exists
   884→if (!existsSync(sessionsDir)) {
   885→  mkdirSync(sessionsDir, { recursive: true });
   886→}
   887→
   888→export const saveSession = (session: Session): void => {
   889→  const path = join(sessionsDir, `${session.id}.json`);
   890→  writeFileSync(path, JSON.stringify(session, null, 2));
   891→};
   892→
   893→export const loadSession = (sessionId: string): Session | null => {
   894→  const path = join(sessionsDir, `${sessionId}.json`);
   895→  if (!existsSync(path)) return null;
   896→  return JSON.parse(readFileSync(path, "utf-8"));
   897→};
   898→
   899→export const deleteSession = (sessionId: string): boolean => {
   900→  const path = join(sessionsDir, `${sessionId}.json`);
   901→  if (!existsSync(path)) return false;
   902→  unlinkSync(path);
   903→  return true;
   904→};
   905→
   906→export const listSessions = (): string[] => {
   907→  return readdirSync(sessionsDir)
   908→    .filter(f => f.endsWith(".json"))
   909→    .map(f => f.replace(".json", ""));
   910→};
   911→```
