   915→## 13. Server Setup
   916→
   917→### 13.1 Express + WebSocket
   918→
   919→```typescript
   920→// server.ts
   921→import express from "express";
   922→import cors from "cors";
   923→import { createServer } from "http";
   924→import { WebSocketServer, WebSocket } from "ws";
   925→import { config } from "./config";
   926→
   927→// Routes
   928→import sessionsRouter from "./routes/sessions";
   929→import messagesRouter from "./routes/messages";
   930→import contextRouter from "./routes/context";
   931→import personasRouter from "./routes/personas";
   932→
   933→const app = express();
   934→const server = createServer(app);
   935→const wss = new WebSocketServer({ server, path: "/ws" });
   936→
   937→// Middleware
   938→app.use(cors({ origin: config.corsOrigin }));
   939→app.use(express.json());
   940→
   941→// Routes
   942→app.use("/api/sessions", sessionsRouter);
   943→app.use("/api/context", contextRouter);   // Wraps Artifact Engine
   944→app.use("/api/personas", personasRouter);
   945→
   946→// WebSocket connections by session
   947→const sessionSubscribers = new Map<string, Set<WebSocket>>();
   948→
   949→wss.on("connection", (ws) => {
   950→  ws.on("message", (data) => {
   951→    const message = JSON.parse(data.toString());
   952→
   953→    switch (message.type) {
   954→      case "SUBSCRIBE":
   955→        if (!sessionSubscribers.has(message.sessionId)) {
   956→          sessionSubscribers.set(message.sessionId, new Set());
   957→        }
   958→        sessionSubscribers.get(message.sessionId)!.add(ws);
   959→        ws.send(JSON.stringify({ type: "SUBSCRIBED", sessionId: message.sessionId }));
   960→        break;
   961→
   962→      case "UNSUBSCRIBE":
   963→        sessionSubscribers.get(message.sessionId)?.delete(ws);
   964→        break;
   965→
   966→      case "PING":
   967→        ws.send(JSON.stringify({ type: "PONG" }));
   968→        break;
   969→    }
   970→  });
   971→
   972→  ws.on("close", () => {
   973→    // Remove from all subscriptions
   974→    sessionSubscribers.forEach(subs => subs.delete(ws));
   975→  });
   976→});
   977→
   978→// Export for use in routes
   979→export const broadcast = (sessionId: string, message: object) => {
   980→  const subs = sessionSubscribers.get(sessionId);
   981→  if (subs) {
   982→    const data = JSON.stringify(message);
   983→    subs.forEach(ws => {
   984→      if (ws.readyState === WebSocket.OPEN) {
   985→        ws.send(data);
   986→      }
   987→    });
   988→  }
   989→};
   990→
   991→server.listen(config.port, () => {
   992→  console.log(`Server running on port ${config.port}`);
   993→});
   994→```
