### 5.2 Session

```typescript
interface Session {
  id: string;
  corpusId: string;
  contextScope: ContextScope;
  personaId: string;
  title: string;
  mode: SessionMode;
  cards: TurnCard[];
  createdAt: string;
  updatedAt: string;

  // Distillation (updated periodically)
