## 12. File Operations

### 12.1 Session Storage

```typescript
// storage/json.ts
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, unlinkSync } from "fs";
import { join } from "path";
import { config } from "../config";

const sessionsDir = join(config.dataDir, "sessions");

// Ensure directory exists
if (!existsSync(sessionsDir)) {
  mkdirSync(sessionsDir, { recursive: true });
}

export const saveSession = (session: Session): void => {
  const path = join(sessionsDir, `${session.id}.json`);
  writeFileSync(path, JSON.stringify(session, null, 2));
};

export const loadSession = (sessionId: string): Session | null => {
  const path = join(sessionsDir, `${sessionId}.json`);
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, "utf-8"));
};

export const deleteSession = (sessionId: string): boolean => {
  const path = join(sessionsDir, `${sessionId}.json`);
  if (!existsSync(path)) return false;
  unlinkSync(path);
  return true;
};

export const listSessions = (): string[] => {
  return readdirSync(sessionsDir)
    .filter(f => f.endsWith(".json"))
    .map(f => f.replace(".json", ""));
};
```

