## 10. OpenAI Integration

### 10.1 Client Setup

```typescript
// services/openai.ts
import OpenAI from "openai";
import { config } from "../config";

export const openai = new OpenAI({
  apiKey: config.openaiApiKey,
});
```

### 10.2 Streaming Handler

```typescript
export const streamCompletion = async (
  messages: ChatMessage[],
  onChunk: (content: string, index: number) => void,
  onComplete: (fullContent: string) => void,
  onError: (error: Error) => void
): Promise<void> => {
  try {
    const stream = await openai.chat.completions.create({
      model: config.model,  // "gpt-4" or "gpt-4-turbo"
      messages,
      stream: true,
    });

    let fullContent = "";
    let index = 0;

    for await (const chunk of stream) {
      const content = chunk.choices[0]?.delta?.content || "";
      if (content) {
        fullContent += content;
        onChunk(content, index++);
      }
    }

    onComplete(fullContent);
  } catch (error) {
    onError(error as Error);
  }
};
```

### 10.3 Message Building

```typescript
export const buildMessages = (
  systemPrompt: string,
  cards: TurnCard[],
  newUserMessage: string
): ChatMessage[] => {
  const messages: ChatMessage[] = [
    { role: "system", content: systemPrompt }
  ];

  // Add conversation history
  for (const card of cards) {
    messages.push({ role: "user", content: card.userContent });
    messages.push({ role: "assistant", content: card.aiContent });
  }

  // Add new message
  messages.push({ role: "user", content: newUserMessage });

  return messages;
};
```

